<template>
  <main class="presentation-page">
    <nav class="top-nav"><button class="brand" @click="router.push('/dashboard')"><b>D</b><span>Dokiai Academic<small>PRESENTATION STUDIO</small></span></button><div><button @click="router.push('/dashboard')">工作台</button><button @click="router.push('/projects')">我的项目</button><button class="active">PPT生成</button><button @click="router.push('/points')">积分中心</button></div></nav>
    <section class="hero"><div><small>DOKIAI PRESENTATION STUDIO</small><h1>PPT智能生成</h1><p>上传论文、开题报告或项目文档，生成可编辑的学术答辩PPT。</p></div><aside><b>{{ project?.progress || 0 }}%</b><span>{{ stageLabels[stage-1] }}</span></aside></section>
    <ol class="steps"><li v-for="(label,i) in stageLabels" :key="label" :class="{active:stage===i+1,done:stage>i+1}"><b>{{ i+1 }}</b><span>{{ label }}</span></li></ol>

    <section v-if="stage===1" class="workspace two-col">
      <article class="panel upload-panel"><header><small>STEP 01</small><h2>上传源文档</h2><p>先在本地解析内容、图片和表格，再交给AI设计目录。</p></header><label class="drop-zone"><input type="file" accept=".doc,.docx,.pdf,.pptx,.txt,.md,.markdown" @change="selectFile"><b>＋</b><strong>{{ file?.name || '选择文档文件' }}</strong><span>DOCX · PDF · PPTX · TXT · Markdown</span><em v-if="file">{{ formatBytes(file.size) }}</em></label></article>
      <article class="panel form-panel"><header><small>PROJECT PROFILE</small><h2>答辩信息</h2></header><div class="form-grid"><label class="wide">PPT题目<input v-model="form.topic" placeholder="未填写时从文档提取"></label><label class="wide">英文题名<input v-model="form.englishTopic" placeholder="可选，由AI生成"></label><label>汇报人<input v-model="form.presenter"></label><label>专业<input v-model="form.major"></label><label>指导老师<input v-model="form.advisor"></label><label>学号<input v-model="form.studentNumber"></label><label>目标页数<input v-model.number="form.targetSlideCount" type="number" min="8" max="40"></label></div><button class="primary" :disabled="!file||busy" @click="createAndUpload">{{ busy?'正在上传…':'上传并开始解析 →' }}</button></article>
    </section>

    <section v-else-if="stage===2" class="workspace"><article class="panel analysis"><header><small>STEP 02</small><h2>AI内容解析</h2><p>完整保留原始顺序、图表关系与来源位置。</p></header><div class="source-file"><i>P</i><span><b>{{ project.source_file_name }}</b><small>{{ formatBytes(project.source_file_size) }}</small></span><em>解析完成</em></div><div class="metrics"><article><b>{{ analysis.headings?.length||0 }}</b><span>识别标题</span></article><article><b>{{ analysis.imageCount||0 }}</b><span>图片素材</span></article><article><b>{{ analysis.tableCount||0 }}</b><span>表格</span></article><article><b>{{ analysis.characterCount||0 }}</b><span>内容字符</span></article></div><div class="detected"><h3>识别到的结构</h3><span v-for="item in (analysis.headings||[]).slice(0,10)" :key="item">{{ item }}</span></div><footer><button class="secondary" @click="stage=1">返回</button><button class="primary" :disabled="busy" @click="makeOutline">{{ busy?'AI正在设计目录…':'生成PPT目录 →' }}</button></footer></article></section>

    <section v-else-if="stage===3" class="workspace split-aside"><article class="panel outline-editor"><header><small>STEP 03</small><h2>确认目录</h2><p>目录至少4项，可修改名称、页数和顺序。</p></header><div class="outline-list"><article v-for="(item,i) in outline" :key="item.id||i"><b>{{ String(i+1).padStart(2,'0') }}</b><div><input v-model="item.title" maxlength="20"><textarea v-model="item.description" maxlength="80"></textarea></div><label>内容页<input v-model.number="item.target_slides" type="number" min="1" max="8"></label><div class="row-actions"><button :disabled="i===0" @click="move(outline,i,-1)">↑</button><button :disabled="i===outline.length-1" @click="move(outline,i,1)">↓</button><button :disabled="outline.length<=4" @click="outline.splice(i,1)">×</button></div></article></div><button class="add" @click="outline.push({title:'新目录',description:'',target_slides:2})">＋ 新增目录</button><footer><span>AI状态：{{ providerStatus }}</span><button class="primary" :disabled="outline.length<4||busy" @click="saveAndPlan">确认目录并规划幻灯片 →</button></footer></article><aside class="panel rules"><small>QUALITY RULES</small><h3>生成前质量规则</h3><p>✓ 每页顶部必须有标题</p><p>✓ 正文框最多4个</p><p>✓ 每个正文框最多20字</p><p>✓ 目录至少4项</p><p>✓ 保留图片原始比例</p></aside></section>

    <section v-else-if="stage===4" class="workspace"><article class="panel slide-plan"><header><small>STEP 04</small><h2>幻灯片规划</h2><p>每页只表达一个核心观点，可逐页调整。</p></header><div class="plan-grid"><article v-for="(slide,i) in slides" :key="slide.id" @click="editSlide(slide)"><span>{{ String(i+1).padStart(2,'0') }}</span><small>{{ slide.layout_type }}</small><h3>{{ slide.title }}</h3><p v-for="box in parseBoxes(slide.body_boxes_json)" :key="box">{{ box }}</p><footer><em :class="slide.validation_status.toLowerCase()">{{ slide.validation_status }}</em><button @click.stop="regenerate(slide)">重新生成</button></footer></article></div><footer><span>预计完整PPT {{ expectedPages }} 页</span><button class="primary" :disabled="busy" @click="startGenerate">开始生成PPTX →</button></footer></article></section>

    <section v-else-if="stage===5" class="workspace"><article class="panel generating"><div class="progress-ring"><b>{{ project.progress||65 }}%</b></div><small>STEP 05 · PPT GENERATION</small><h2>{{ project.current_stage||'正在生成可编辑PPTX' }}</h2><p>正在检查标题、20字限制、素材比例与固定结尾页。</p><div class="check-flow"><span>✓ 文档解析</span><span>✓ 目录确认</span><span>✓ 幻灯片规划</span><span class="running">● PPTX生成与校验</span></div></article></section>

    <section v-else class="workspace result-layout"><article class="panel result"><header><small>STEP 06</small><h2>预览与下载</h2><p>已生成可编辑的 Dokiai Academic 学术答辩PPT。</p></header><div class="file-result"><i>P</i><span><b>{{ cleanTopic }}.pptx</b><small>{{ slides.length + outline.length + 4 }} 页 · 16:9 · 可编辑PPTX</small></span><em>质量检查通过</em></div><div class="quality"><span>✓ 每页均有标题</span><span>✓ 正文框不超过20字</span><span>✓ 图片保持原始比例</span><span>✓ 未来展望为倒数第二页</span><span>✓ 谢谢大家为最后一页</span></div><button class="primary download" @click="download">下载PPTX</button><h3>幻灯片缩略图</h3><div class="thumbs"><article><b>{{ form.topic||project.topic }}</b><small>封面</small></article><article><b>目录</b><small>目录页</small></article><article v-for="slide in slides" :key="slide.id"><b>{{ slide.title }}</b><small>{{ slide.layout_type }}</small></article><article><b>未来展望</b><small>结尾</small></article><article><b>谢谢大家</b><small>THANK YOU</small></article></div></article></section>

    <div v-if="editing" class="dialog-mask" @click.self="editing=null"><section class="dialog"><header><h3>编辑当前页</h3><button @click="editing=null">×</button></header><label>标题<input v-model="editing.title" maxlength="24"></label><label v-for="(_,i) in editing.boxes" :key="i">正文框 {{ i+1 }}（最多20字）<input v-model="editing.boxes[i]" maxlength="20"><small>{{ visibleLength(editing.boxes[i]) }}/20</small></label><label>布局<select v-model="editing.layout"><option>KEYWORDS</option><option>IMAGE_TEXT</option><option>TEXT_IMAGE</option><option>BIG_IMAGE</option></select></label><footer><button class="secondary" @click="editing=null">取消</button><button class="primary" @click="saveSlide">保存当前页</button></footer></section></div>
  </main>
</template>

<script setup>
import { computed, onMounted, ref } from 'vue';import { useRoute,useRouter } from 'vue-router';import { ElMessage } from 'element-plus';import { createPptProject,getPptProject,uploadPptSource,analyzePptProject,generatePptOutline,savePptOutline,planPptSlides,updatePptSlide,regeneratePptSlide,generatePptFile,getPptProgress,downloadPptFile } from '../../api/rewrite'
const router=useRouter(),route=useRoute(),stage=ref(1),busy=ref(false),file=ref(null),project=ref({progress:0}),analysis=ref({}),outline=ref([]),slides=ref([]),editing=ref(null),providerStatus=ref('--');const stageLabels=['上传文档','AI内容解析','目录确认','幻灯片规划','PPT生成','预览下载'];const form=ref({topic:'',englishTopic:'',presenter:'',major:'',advisor:'',studentNumber:'',targetSlideCount:16});const cleanTopic=computed(()=>String(project.value.topic||form.value.topic||'未命名学术答辩').replace(/[\\/:*?"<>|]/g,'_'));const expectedPages=computed(()=>2+outline.value.length+slides.value.length+2)
function selectFile(e){file.value=e.target.files?.[0]||null}function formatBytes(v){const n=Number(v||0);return n>1048576?(n/1048576).toFixed(1)+' MB':(n/1024).toFixed(1)+' KB'}function parseBoxes(v){try{return Array.isArray(v)?v:JSON.parse(v||'[]')}catch{return[]}}function visibleLength(v){return String(v||'').replace(/\s/g,'').length}function move(items,i,d){const next=i+d;if(next<0||next>=items.length)return;[items[i],items[next]]=[items[next],items[i]]}
async function createAndUpload(){busy.value=true;try{project.value=await createPptProject(form.value);project.value=await uploadPptSource(project.value.id,file.value);project.value=await analyzePptProject(project.value.id);analysis.value=JSON.parse(project.value.analysis_json||'{}');stage.value=2;ElMessage.success('文档解析完成')}catch(e){ElMessage.error(e?.responseData?.message||e.message||'解析失败')}finally{busy.value=false}}
async function makeOutline(){busy.value=true;try{const data=await generatePptOutline(project.value.id);project.value=data;outline.value=data.outline||[];providerStatus.value=data.providerStatus||'--';stage.value=3}catch(e){ElMessage.error(e?.responseData?.message||'目录生成失败')}finally{busy.value=false}}
async function saveAndPlan(){busy.value=true;try{await savePptOutline(project.value.id,outline.value.map((x,i)=>({title:x.title,description:x.description,targetSlides:x.target_slides,sectionOrder:i+1})));const data=await planPptSlides(project.value.id);project.value=data;outline.value=data.outline||[];slides.value=data.slides||[];stage.value=4}catch(e){ElMessage.error(e?.responseData?.message||'规划失败')}finally{busy.value=false}}
function editSlide(s){editing.value={id:s.id,title:s.title,boxes:[...parseBoxes(s.body_boxes_json)],layout:s.layout_type}}
async function saveSlide(){const data=await updatePptSlide(project.value.id,editing.value.id,{title:editing.value.title,bodyBoxes:editing.value.boxes,layoutType:editing.value.layout});slides.value=data.slides||[];editing.value=null;ElMessage.success('当前页已保存')}
async function regenerate(s){const data=await regeneratePptSlide(project.value.id,s.id);slides.value=data.slides||[];ElMessage.success('当前页已重新生成')}
async function startGenerate(){busy.value=true;stage.value=5;try{project.value={...project.value,progress:65,current_stage:'正在生成可编辑PPTX'};await generatePptFile(project.value.id);project.value=await getPptProgress(project.value.id);stage.value=6;ElMessage.success('PPTX生成完成')}catch(e){stage.value=4;ElMessage.error(e?.responseData?.message||e.message||'生成失败')}finally{busy.value=false}}
async function download(){const blob=await downloadPptFile(project.value.id),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=cleanTopic.value+'.pptx';a.click();URL.revokeObjectURL(url)}
async function resume(){if(!route.query.projectId)return;try{const data=await getPptProject(route.query.projectId);project.value=data;outline.value=data.outline||[];slides.value=data.slides||[];analysis.value=JSON.parse(data.analysis_json||'{}');Object.assign(form.value,{topic:data.topic||'',englishTopic:data.english_topic||'',presenter:data.presenter||'',major:data.major||'',advisor:data.advisor||'',studentNumber:data.student_number||'',targetSlideCount:data.target_slide_count||16});stage.value=data.status==='SUCCESS'?6:data.status==='PLANNED'?4:data.status==='OUTLINE_READY'?3:data.status==='ANALYZED'?2:1}catch(e){ElMessage.warning(e?.responseData?.message||'项目暂时无法恢复')}}onMounted(resume)
</script>

<style scoped>
