00}.source-file span,.file-result span{display:grid}.source-file small,.file-result small{color:#9298a8}.source-file em,.file-result em{color:#145b4d;font-style:normal}.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin:18px 0}.metrics article{display:grid;gap:3px;padding:20px;border:1px solid #ebe7f3;border-radius:15px}.metrics b{font-size:28px}.metrics span{color:#8d93a4;font-size:11px}.detected{padding:20px;border:1px solid #ebe7f3;border-radius:16px}.detected span{display:inline-block;margin:5px;padding:7px 10px;border-radius:9px;color:#6654cd;background:#f0edff;font-size:11px}.analysis>footer,.outline-editor>footer,.slide-plan>footer,.dialog footer{display:flex;align-items:center;justify-content:space-between;margin-top:20px}.split-aside{display:grid;grid-template-columns:minmax(0,1fr) 270px;gap:18px}.outline-editor{padding:0 28px 28px}.outline-list{display:grid;gap:10px}.outline-list>article{display:grid;grid-template-columns:45px 1fr 70px auto;gap:12px;align-items:center;padding:13px;border:1px solid #ebe7f3;border-radius:15px}.outline-list>article>b{color:#6e4fff;font-size:20px}.outline-list>article>div{display:grid;gap:6px}.outline-list textarea{min-height:43px;resize:vertical}.outline-list label{display:grid;gap:5px;color:#9096a6;font-size:9px}.row-actions{display:flex!important}.row-actions button{border:0;color:#6e4fff;background:none}.add{margin-top:12px}.rules{align-self:start;padding:25px}.rules h3{margin:8px 0 20px}.rules p{color:#666d80;font-size:12px}.slide-plan{padding:0 28px 28px}.plan-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:13px}.plan-grid>article{position:relative;min-height:185px;padding:18px;border:1px solid #e5e1ee;border-radius:16px;background:linear-gradient(145deg,#fff,#faf8ff);cursor:pointer;transition:.2s}.plan-grid>article:hover{transform:translateY(-4px);box-shadow:0 17px 35px #4b3e7b18}.plan-grid>article>span{color:#6e4fff;font-weight:900}.plan-grid>article>small{float:right;color:#9ba0af}.plan-grid h3{margin:18px 0 9px}.plan-grid p{margin:5px 0;color:#73798b;font-size:11px}.plan-grid footer{position:absolute;right:14px;bottom:13px;left:14px;display:flex;justify-content:space-between}.plan-grid footer em{color:#145b4d;font-size:9px;font-style:normal}.plan-grid footer button{border:0;color:#6e4fff;background:none;font-size:10px}.generating{display:grid;place-items:center;min-height:450px;text-align:center}.progress-ring{display:grid;place-items:center;width:135px;height:135px;margin-bottom:25px;border-radius:50%;background:conic-gradient(#6e4fff 0 65%,#ebe8f3 65%)}.progress-ring:before{content:'';position:absolute;width:106px;height:106px;border-radius:50%;background:#fff}.progress-ring b{z-index:1;font-size:27px}.generating h2{font-size:30px}.generating p{color:var(--muted)}.check-flow{display:flex;gap:9px;margin-top:25px}.check-flow span{padding:9px 12px;border-radius:10px;color:#145b4d;background:#edf7f3;font-size:11px}.check-flow .running{color:#6e4fff;background:#f0edff}.result{padding:0 30px 30px}.file-result{display:grid;grid-template-columns:52px 1fr auto;gap:14px;align-items:center;padding:20px;border-radius:17px;background:#f8f6fd}.quality{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin:18px 0}.quality span{padding:12px;border-radius:11px;color:#145b4d;background:#edf7f3;font-size:11px}.download{font-size:16px}.result>h3{margin-top:30px}.thumbs{display:grid;grid-template-columns:repeat(5,1fr);gap:11px}.thumbs article{display:grid;align-content:end;min-height:120px;padding:13px;border:1px solid #e8e4ef;border-radius:12px;background:linear-gradient(145deg,#fff,#f5f1ff)}.thumbs b{font-size:12px}.thumbs small{color:#9a9fad}.dialog-mask{position:fixed;inset:0;z-index:30;display:grid;place-items:center;background:#28213f55;backdrop-filter:blur(5px)}.dialog{display:grid;gap:13px;width:min(520px,calc(100% - 30px));padding:24px;border-radius:22px;background:#fff;box-shadow:0 30px 90px #221a4455}.dialog header{display:flex;justify-content: